            (root / 'org/teams.yaml').write_text('teams:\n  engineering:\n    manager: r1c_manager\n    workers: [r1c_dev, r1c_review, r1c_qa]\n')
            for name, role in (('r1c_manager', 'manager'), ('r1c_dev', 'worker'),
                               ('r1c_review', 'worker'), ('r1c_qa', 'worker')):
