                    assert tuple(f.conn.iterdump())==before and f.conn.total_changes==changes
                path='/workflows/sequential/settings/admission'
                for raw in (b'{"format":"x","format":"y"}', b' '+s4bytes(admission), b'x'*16385):
                    await setup_request(f,'PUT',path,raw=raw,expected=422,code='sequential_settings_request_invalid')
                f.org.sessions.set_active(f.source.id, f.source.assigned_agent, f.source.current_session_id, org_slug=f.org.slug)
                for headers in ({}, {'authorization':'Bearer synthetic-invalid'}, {'X-Session-ID':f.source.current_session_id},
                                {'X-Session-ID':f.source.current_session_id,'X-HappyRanch-Surface':'cli'}):
                    before=tuple(f.conn.iterdump())
                    await setup_request(f,'PUT',path,body=admission,headers=headers,expected=401)
                    await setup_request(f,'GET',admission_path+'valid-audience',headers=headers,expected=401)
                    await setup_put(f,dict(first,operation_key='save-audience',expected_generation=1),headers=headers,expected=401)
                    await setup_request(f,'GET',operations_path+'unit-a-save',headers=headers,expected=401)
                    assert tuple(f.conn.iterdump())==before
                for suffix in ('','?operation_key=x&operation_key=y','?operation_key=x&extra=x','?operation_key=%20'):
                    await setup_request(f,'GET',path+'/operations'+suffix,expected=422)
                    await setup_request(f,'GET','/workflows/sequential/settings/v2/operations'+suffix,expected=422)
                await setup_request(f,'GET',admission_path+'missing',raw=b'{}',expected=422,code='sequential_settings_request_invalid')
                await setup_request(f,'GET',operations_path+'unit-a-save',raw=b'{}',expected=422,code='sequential_settings_request_invalid')
                await setup_request(f,'PUT',path+'?extra=x',body=admission,expected=422,code='sequential_settings_request_invalid')
                await setup_request(f,'PUT',path+'?x=a&x=b',body=admission,expected=422,code='sequential_settings_request_invalid')
                await setup_request(f,'PUT',path,body=admission,headers={'authorization':'Bearer synthetic-setup-founder','content-type':'text/plain'},expected=422)
                for raw in (b'{"format":"x","format":"y"}', b' '+s4bytes(first), b'x'*16385):
                    await setup_request(f,'PUT','/workflows/sequential/settings/v2',raw=raw,expected=422,code='sequential_settings_request_invalid')
                await setup_request(f,'PUT','/workflows/sequential/settings/v2?extra=x',body=first,expected=422)
                await setup_request(f,'PUT','/workflows/sequential/settings/v2',body=first,
                    headers={'authorization':'Bearer synthetic-setup-founder','content-type':'text/plain'},expected=422)
                await setup_put(f,admission)
                assert setup_no_work(f)==work
                return
            frozen={table:tuple(tuple(row) for row in f.conn.execute('SELECT * FROM '+table+' ORDER BY rowid'))
                for table in ('workflow_seq_settings','workflow_seq_settings_operations')}
            fragments={key:s4bytes(first[key]) for key in ('bindings','limits')}
            allowed_command=setup_admission(first,'unit-a-allow',1)
            allowed=(await setup_put(f,allowed_command)).json()
            assert allowed['original']['generation']==2 and allowed['original']['snapshot']['admission']=='Allowed'
            assert allowed['original']['snapshot']['bindings']==first['bindings'] and allowed['original']['snapshot']['limits']==first['limits']
            readback=(await setup_request(f,'GET',current_path)).json()
            assert readback==allowed['original'], 'A03 independent Allow readback differs'
            assert {key:s4bytes(readback['snapshot'][key]) for key in fragments}==fragments
            for table,old in frozen.items():
                rows=tuple(tuple(row) for row in f.conn.execute('SELECT * FROM '+table+' ORDER BY rowid'))
                assert rows[:-1]==old, ('A03 old row bytes changed',table)
            assert setup_no_work(f)==work
            with sqlite3.connect(f.db.path) as reopened:
                row=reopened.execute('SELECT snapshot_bytes FROM workflow_seq_settings WHERE id=?',(readback['id'],)).fetchone()[0]
                assert json.loads(row)==readback['snapshot'], 'A03 reopened Allow snapshot differs'
            if case=='race':
                import asyncio
                for index,(left_kind,right_kind) in enumerate((('Allowed','Disabled'),('Save','Allowed'),('Save','Disabled'))):
                    current=(await setup_request(f,'GET',current_path)).json()
                    contenders=[]
                    for side,action in (('left',left_kind),('right',right_kind)):
                        body=deepcopy(first) if action=='Save' else setup_admission(first,'unused',current['generation'],action)
                        body.update(operation_key='race-'+side+'-'+str(index),expected_generation=current['generation'])
                        if action=='Save':
                            body['bindings'][0]['principal'],body['bindings'][3]['principal']=body['bindings'][3]['principal'],body['bindings'][0]['principal']
                            body['limits']=dict(max_visits=11,max_events=120,max_recoveries=1,node_revisions=dict(develop=0))
                        contenders.append(body)
                    left,right=contenders
                    frozen={table:tuple(tuple(row) for row in f.conn.execute('SELECT * FROM '+table+' ORDER BY rowid'))
                        for table in ('workflow_seq_settings','workflow_seq_settings_operations')}
                    # Both tasks start outside the shared writer. No barrier is
                    # inserted inside its lock, and no production seam is added.
                    native=f.org.workflow_authority._async_writer_lock
                    arrived=asyncio.Event()
                    class ObservedLock:
                        count=0
                        def __getattr__(self,name):
                            return getattr(native,name)
                        async def __aenter__(self):
                            self.count+=1
                            if self.count==2:
                                arrived.set()
                            return await native.__aenter__()
                        async def __aexit__(self,*args):
                            return await native.__aexit__(*args)
                    await native.acquire()
                    with patch.object(f.org.workflow_authority,'_async_writer_lock',ObservedLock()):
                        tasks=[asyncio.create_task(setup_put(f,body,expected=None)) for body in (left,right)]
                        try:
                            await asyncio.wait_for(arrived.wait(),timeout=5)
                        finally:
                            native.release()
                        outcomes=await asyncio.gather(*tasks)
                    assert sorted(r.status_code for r in outcomes)==[200,409]
                    loser=next(r for r in outcomes if r.status_code==409)
                    assert loser.json()['detail']['code']=='sequential_settings_generation_stale'
                    winner=next(body for body,response in zip(contenders,outcomes) if response.status_code==200)
                    observed=(await setup_request(f,'GET',current_path)).json()
                    assert observed['generation']==current['generation']+1
                    assert observed['snapshot']['admission']==(current['snapshot']['admission'] if 'bindings' in winner else winner['admission'])
                    for key in ('bindings','limits'):
                        assert observed['snapshot'][key]==(winner[key] if 'bindings' in winner else current['snapshot'][key])
                    for table,old in frozen.items():
                        rows=tuple(tuple(row) for row in f.conn.execute('SELECT * FROM '+table+' ORDER BY rowid'))
                        assert len(rows)==len(old)+1 and rows[:-1]==old, ('A06 append delta/old bytes',table)
                    assert f.conn.execute('SELECT count(*) FROM workflow_seq_settings_operations WHERE operation_key IN (?,?)',(left['operation_key'],right['operation_key'])).fetchone()[0]==1
                assert setup_no_work(f)==work
                return
            if case=='pins':
                from runtime.workflows.sequential_engine import admit_uncommitted
                from runtime.workflows.sequential_start import prepare_generic_start
                from runtime.workflows.sequential_release import read_generic_coding_release
                from runtime.workflows.sequential_contracts import GenericLimits
                compiled=read_generic_coding_release()
                start=deepcopy(f.command)
                start.update(operation_key='unit-a-run',definition=first['definition'],settings=dict(generation=2,snapshot_digest=allowed['original']['snapshot_digest']),
                    lower_limits=first['limits'],role_overrides=[],step_overrides=[])
                raw=assignment_bytes(start)
                claim=RetryClaim.from_task(f.source,result_row_id=f.conn.execute('SELECT id FROM task_results WHERE task_id=?',(f.source.id,)).fetchone()[0])
                capture=prepare_generic_start(f.org,start=raw,source=claim)
                setting=dict(f.conn.execute('SELECT * FROM workflow_seq_settings WHERE id=?',(allowed['original']['id'],)).fetchone())
                carrier=TaskRecord(id='unit-a-carrier',parent_task_id=f.source.id,assigned_agent='s3_manager',team='engineering',task_type='subtask',brief='Private inert carrier')
                visit=TaskRecord(id='unit-a-visit',parent_task_id=carrier.id,assigned_agent='s3_author',team='engineering',task_type='subtask',brief='Private inert visit',
                    model_override=f.source.model_override,reasoning_effort_override=f.source.reasoning_effort_override,override_source='manager')
                with f.org.workflow_authority.admission_writer(capture.authority) as conn:
                    ids=admit_uncommitted(conn,f.db,org_slug='scratch',compiled=compiled,settings_row=setting,start=raw,source=claim,
                        carrier_task=carrier,visit_task=visit,original_limits=GenericLimits.model_validate(first['limits']),authority=f.org.workflow_authority,capture=capture)
                work=setup_no_work(f)
            changed=deepcopy(first);changed.update(operation_key='unit-a-save-allowed',expected_generation=2)
            changed['bindings'][0]['principal'],changed['bindings'][3]['principal']=changed['bindings'][3]['principal'],changed['bindings'][0]['principal']
            changed['limits']=dict(max_visits=11,max_events=120,max_recoveries=1,node_revisions=dict(develop=0))
            kept=(await setup_put(f,changed)).json()
            assert kept['original']['snapshot']['admission']=='Allowed' and kept['original']['generation']==3
            assert kept['original']['snapshot']['limits']==changed['limits']
            disabled=(await setup_put(f,setup_admission(first,'unit-a-disable',3,'Disabled'))).json()
            assert disabled['original']['generation']==4 and disabled['original']['snapshot']['admission']=='Disabled'
            changed.update(operation_key='unit-a-save-disabled',expected_generation=4)
            last=(await setup_put(f,changed)).json()
            assert last['original']['generation']==5 and last['original']['snapshot']['admission']=='Disabled'
            assert setup_no_work(f)==work
            if case=='pins':
                from runtime.workflows.sequential_run_validation import validate_selected_run_uncommitted
                row=s4row(f,'workflow_seq_runs',ids.run_id)
                with f.db.coherent_read_view() as conn:
                    validate_selected_run_uncommitted(conn,org_slug='scratch',run_id=ids.run_id,scope='admission')
                capture=prepare_generic_start(f.org,start=raw,source=claim)
                before=setup_no_work(f)
                with f.org.workflow_authority.admission_writer(capture.authority) as conn:
                    replay=admit_uncommitted(conn,f.db,org_slug='scratch',compiled=compiled,settings_row=setting,start=raw,source=claim,
                        carrier_task=carrier,visit_task=visit,original_limits=GenericLimits.model_validate(first['limits']),authority=f.org.workflow_authority,capture=capture)
                assert replay==ids and setup_no_work(f)==before, 'A07 admitted replay changed pins/work'
                for pin in (start['settings'],dict(generation=5,snapshot_digest=last['original']['snapshot_digest'])):
                    source=TaskRecord(id='unit-a-fresh-source-'+str(pin['generation']),assigned_agent='s3_manager',team='engineering',
                        task_type='task',status='in_progress',current_session_id='unit-a-fresh-session-'+str(pin['generation']),brief='Private fresh source')
                    f.db.insert_task(source)
                    result=f.conn.execute('INSERT INTO task_results(task_id,agent,session_id,status,created_at) VALUES (?,?,?,?,?)',
                        (source.id,source.assigned_agent,source.current_session_id,'completed',source.created_at.isoformat())).lastrowid
                    f.conn.commit()
                    before=setup_no_work(f)
                    fresh=deepcopy(start);fresh.update(operation_key='fresh-'+str(pin['generation']),settings=pin)
                    try:
                        prepare_generic_start(f.org,start=assignment_bytes(fresh),source=RetryClaim.from_task(source,result_row_id=result))
                    except ValueError as exc:
                        assert ('settings_generation_stale' if pin['generation']==2 else 'sequential_admission_pin_conflict') in str(exc), str(exc)
                    else:
                        raise AssertionError('A07 fresh disabled/stale settings admitted')
                    assert setup_no_work(f)==before, 'A07 refused fresh attempt allocated work'
                work=setup_no_work(f)
                assert (await s7read(f,'/workflows/sequential/views/v2/runs/'+ids.run_id))['run']['settings_id']==allowed['original']['id']
            if case=='rollback':
                # Real owner transaction cut: fault its existing post-insert
                # complete reader, never a new production injection hook.
                from runtime.workflows import sequential_settings as owner
                original=owner.read_sequential_history
                def after_insert(conn,**kwargs):
                    if conn.execute('SELECT 1 FROM workflow_seq_settings_operations WHERE operation_key=?',('unit-a-rollback',)).fetchone():
                        raise ValueError('private precommit fault')
                    return original(conn,**kwargs)
                def business():
                    tables=[r[0] for r in f.conn.execute("SELECT name FROM sqlite_schema WHERE type='table' AND (name GLOB 'workflow_seq_*' OR name IN ('tasks','task_results')) ORDER BY name")]
                    return {table:tuple(tuple(r) for r in f.conn.execute('SELECT * FROM '+table+' ORDER BY rowid')) for table in tables}
                before=business()
                with patch.object(owner,'read_sequential_history',after_insert):
                    await setup_put(f,setup_admission(first,'unit-a-rollback',5),expected=409,code='sequential_history_unverified')
                assert business()==before and not f.conn.in_transaction, 'A09 partial business append or retained transaction'
            # Original Save/admission are independent of newer opposite-kind work.
            before,changes,sql=tuple(f.conn.iterdump()),f.conn.total_changes,[]
            with patch('runtime.workflows.sequential_settings.native_writer',side_effect=AssertionError('replay acquired writer')):
                f.conn.set_trace_callback(sql.append)
                try:
                    assert (await setup_put(f,first)).json()==saved
                    assert (await setup_put(f,allowed_command)).json()==allowed
                    assert (await setup_request(f,'GET',operations_path+'unit-a-save')).json()==saved
                    assert (await setup_request(f,'GET',admission_path+'unit-a-allow')).json()==allowed
                    await setup_request(f,'GET',admission_path+'absent',expected=404,code='sequential_settings_operation_not_found')
                finally:
                    f.conn.set_trace_callback(None)
            assert tuple(f.conn.iterdump())==before and f.conn.total_changes==changes
            assert not any(stmt.lstrip().split(' ',1)[0].upper() in ('INSERT','UPDATE','DELETE','REPLACE','COMMIT') for stmt in sql)
            if case=='replay':
                # A second actual private tenant has its own registrar/history;
                # a founder bearer cannot make its key lookup read another DB.
                with s3_fixture(slug='foreign') as foreign:
                    foreign_before=tuple(foreign.conn.iterdump())
                    await setup_request(foreign,'GET',admission_path+'unit-a-allow',expected=404,code='sequential_settings_operation_not_found')
                    await setup_request(foreign,'GET',operations_path+'unit-a-save',expected=404,code='sequential_settings_operation_not_found')
                    assert tuple(foreign.conn.iterdump())==foreign_before
                # Reopen the actual database facade used by the routes, then
                # repeat originals without acquiring any writer custody.
                with s5reopen(f) as reopened:
                    reopened.rollback()  # Route owns its own read transaction.
                    with patch.object(f.db,'_conn',reopened), patch('runtime.workflows.sequential_settings.native_writer',side_effect=AssertionError('reopened replay acquired writer')):
                        assert (await setup_put(f,first)).json()==saved
                        assert (await setup_put(f,allowed_command)).json()==allowed
                        assert (await setup_request(f,'GET',operations_path+'unit-a-save')).json()==saved
                        assert (await setup_request(f,'GET',admission_path+'unit-a-allow')).json()==allowed
            for body in (dict(setup_admission(first,'unit-a-allow',1),definition=f.compiled.pin.model_dump(mode='json')),setup_admission(first,'unit-a-allow',2),setup_admission(first,'unit-a-allow',1,'Disabled'),
                         setup_admission(first,'unit-a-save',0),dict(first,operation_key='unit-a-allow',expected_generation=1)):
                await setup_put(f,body,expected=409,code='sequential_settings_operation_conflict')
            await setup_put(f,setup_admission(first,'unit-a-stale',1),expected=409,code='sequential_settings_generation_stale')
            same=setup_admission(first,'unit-a-same',5,'Disabled')
            final=await setup_put(f,same)
            assert final.json()['original']['generation']==6
            assert (await setup_put(f,same)).content==final.content
            read_sequential_history(f.conn,expected_org_slug='scratch')
            with sqlite3.connect(f.db.path) as reopened:
                reopened.execute('PRAGMA foreign_keys=ON')
                read_sequential_history(reopened,expected_org_slug='scratch')
            if case=='rollback':
                lost=setup_admission(first,'unit-a-response-lost',6)
                await setup_put(f,lost)  # Deliberately discard the real committed response.
                newer=dict(changed,operation_key='unit-a-after-loss',expected_generation=7)
                await setup_put(f,newer)
                recovered=(await setup_request(f,'GET',admission_path+lost['operation_key'])).json()
                assert recovered['command']==lost and recovered['original']['generation']==7
                assert (await setup_request(f,'GET',current_path)).json()['generation']==8
                assert f.conn.execute('SELECT count(*) FROM workflow_seq_settings_operations WHERE operation_key=?',(lost['operation_key'],)).fetchone()[0]==1
            print('TRANSCRIPT unit-a Save -> Allow -> readback -> Save-while-Allowed -> replay -> stale -> Disable',
                json.dumps(dict(save=saved,allow=allowed,save_allowed=kept,disable=disabled)),flush=True)

    def s7legacy(f):
        from runtime.workflows.sequential_definition import compile_definition
        from runtime.workflows.sequential_contracts import Limits
        limits = dict(content_returns=0, max_content_epochs=1, max_visits=1, max_events=4)
        definition = dict(format='workflow-sequential-definition@1', identity='release/synthetic/history', version=1,
            description='Private retained history', required_inputs=[dict(name='request', contract='bounded-text@1', required=True)],
            roles=dict(author=dict(kind='agent', executable=True, eligibility='worker', independent_of=[])),
            entry_node='author', nodes=[dict(id='author', role='author', responsibilities=['Write retained report'],
                inputs=[dict(name='request', source='run.request', required=True)],
                output_contract=dict(slot='document', type='immutable-document@1'), completion_checks=['immutable-document@1'],
                outcomes=dict(produced=dict(action='terminal', condition='done'), BLOCK=dict(action='fail', code='blocked')))],
            limits=limits, terminal_conditions=dict(done=dict(output='document', requires=['immutable-document@1', 'native-success-and-positive-outer-settlement@1'])))
        raw = s4bytes(definition)
        compiled = compile_definition(raw, source_digest=hashlib.sha256(raw).hexdigest())
        pin = compiled.pin
        bindings = [dict(role='author', principal='s3_author')]
        saved = s4bytes(dict(format='workflow-sequential-settings-storage@1', definition=pin.model_dump(mode='json'),
            bindings=bindings, limits=limits, admission='Allowed'))
        digest = hashlib.sha256(saved).hexdigest()
        request = s4bytes(dict(format='workflow-sequential-settings-operation-storage@1', operation_key='s7-save',
            principal='founder', settings_id='s7-settings', expected_generation=0, snapshot_digest=digest))
        receipt = s4bytes(dict(format='workflow-sequential-settings-receipt-storage@1', operation_id='s7-operation',
            settings_id='s7-settings', generation=1, snapshot_digest=digest))
        f.conn.execute('INSERT INTO workflow_seq_definitions VALUES (?,?,?,?,?,?,?,?,?,?)',
            ('s7-definition', pin.identity, pin.version, raw, pin.definition_digest, pin.source_digest,
             pin.compiler, pin.validator, pin.interpreter, pin.capabilities))
        f.conn.execute('INSERT INTO workflow_seq_settings VALUES (?,?,?,?,?,?,?)',
            ('s7-settings', 'scratch', 's7-definition', pin.identity, 1, saved, digest))
        f.conn.execute('INSERT INTO workflow_seq_settings_operations VALUES (?,?,?,?,?,?,?,?,?)',
            ('s7-operation', 'scratch', 'founder', 's7-save', request, hashlib.sha256(request).hexdigest(), 's7-settings', receipt, hashlib.sha256(receipt).hexdigest()))
        f.conn.commit()
        source = TaskRecord(id='s7-source', assigned_agent='s3_manager', team='engineering', task_type='task',
            status='in_progress', current_session_id='s7-session', brief='Retained source')
        f.db.insert_task(source)
        result = f.conn.execute('INSERT INTO task_results(task_id,agent,session_id,status,created_at) VALUES (?,?,?,?,?)',
            (source.id, source.assigned_agent, source.current_session_id, 'completed', source.created_at.isoformat())).lastrowid
        f.conn.commit()
        start = s4bytes(dict(format='workflow-sequential-start@1', operation_key='s7-start', definition=pin.model_dump(mode='json'),
            settings=dict(generation=1, snapshot_digest=digest), request='Retained request', inputs=[], bindings=bindings, lower_limits=limits))
        capture = f.org.workflow_authority.capture_admission()
        setting = dict(f.conn.execute("SELECT * FROM workflow_seq_settings WHERE id='s7-settings'").fetchone())
        with f.org.workflow_authority.admission_writer(capture) as writer:
            ids = admit_uncommitted(writer, f.db, org_slug='scratch', compiled=compiled, settings_row=setting, start=start,
                source=RetryClaim.from_task(source, result_row_id=result), original_limits=Limits(**limits),
                carrier_task=TaskRecord(id='s7-carrier', parent_task_id=source.id, assigned_agent=source.assigned_agent,
                    team='engineering', task_type='subtask', brief='Retained carrier'),
                visit_task=TaskRecord(id='s7-task', parent_task_id='s7-carrier', assigned_agent='s3_author',
                    team='engineering', task_type='subtask', brief='Retained visit'),
                authority=f.org.workflow_authority, capture=capture)
        return ids

    for case in (S7A_CASES if s7a_case or not sys.argv[1:] else ()):
        if s7a_case not in (None, 'all', case):
            continue
        import asyncio
        path = '/workflows/sequential/views/v2/runs'
        if case in ('task_scoped_data', 'task_empty', 'task_corruption', 'task_unrelated', 'task_absent'):
            from runtime.workflows import sequential_history, sequential_views
            from runtime.workflows.sequential_control import validate_control_write

            def damage(f, table, sql, args):
                # Synthetic scratch corruption with exact canonical triggers
                # restored BEFORE observing the production reader.
                triggers = [tuple(row) for row in f.conn.execute(
                    "SELECT name,sql FROM sqlite_schema WHERE type='trigger' AND tbl_name=?", (table,))]
                f.conn.commit()
                f.conn.execute('PRAGMA foreign_keys=OFF')
                for name, _ in triggers:
                    f.conn.execute('DROP TRIGGER "' + name + '"')
                f.conn.execute(sql, args)
                for _, ddl in triggers:
                    f.conn.execute(ddl)
                f.conn.commit()
                f.conn.execute('PRAGMA foreign_keys=ON')

            with s4fixture() as f:
                task_path = '/tasks/' + f.source.id + '/sequential-workflows'
                if case == 'task_scoped_data':
                    # Real route + schema + replay + current authority. Only
                    # the forbidden org-wide data reader is intercepted.
                    with patch.object(sequential_views, 'read_sequential_history',
                            side_effect=AssertionError('task called whole-history reader')):
                        body = asyncio.run(s7read(f, task_path))
                    assert [row['id'] for row in body['runs']] == [f.ids.run_id]
                    assert body['runs'][0]['tasks'][2]['task_id'] == f.ids.visit_task_id
                elif case == 'task_empty':
                    f.db.insert_task(TaskRecord(id='ordinary-task', assigned_agent='s3_manager',
                        team='engineering', brief='No workflows'))
                    from runtime.workflows import sequential_task_history
                    selected_read = sequential_task_history._read_selected
                    def empty_read(conn, metadata, table, budget, where, args, **kwargs):
                        assert table in ('workflow_seq_runs', 'workflow_seq_visits',
                            'workflow_seq_source_wait_sets', 'workflow_seq_source_memberships',
                            'workflow_seq_schema_versions'), ('empty scanned data', table)
                        assert where != '1' or table == 'workflow_seq_schema_versions'
                        return selected_read(conn, metadata, table, budget, where, args, **kwargs)
                    with patch.object(sequential_views, 'read_sequential_history',
                            side_effect=AssertionError('empty task called whole-history reader')), patch.object(
                            sequential_history, '_legacy_history', side_effect=AssertionError('empty scanned legacy')), patch.object(
                            sequential_task_history, '_read_selected', side_effect=empty_read):
                        body = asyncio.run(s7read(f, '/tasks/ordinary-task/sequential-workflows'))
                    assert body['runs'] == [] and body['storage'] == 'readable'
                elif case == 'task_absent':
                    with patch.object(f.org.workflow_authority, 'capture_admission',
                            side_effect=AssertionError('absent task reached authority/history')):
                        body = asyncio.run(s7read(f, '/tasks/missing/sequential-workflows', expected=404))
                    assert body['detail']['code'] == 'task_not_found'
                elif case == 'task_unrelated':
                    old = s7legacy(f)
                    damage(f, 'workflow_seq_events',
                        "UPDATE workflow_seq_events SET event_digest=? WHERE run_id=?", ('0'*64, old.run_id))
                    body = asyncio.run(s7read(f, task_path))
                    assert [row['id'] for row in body['runs']] == [f.ids.run_id], 'unrelated corruption hid real data'
                    # Same corruption STILL refuses full v2 list/detail and the
                    # actual cancel and new-start admission paths.
                    for url in (path, path + '/' + f.ids.run_id):
                        refused = asyncio.run(s7read(f, url, expected=409))
                        assert refused['detail']['code'] == 'history_unverified'
                    for operation in (
                            lambda: f.admit(dict(f.command, operation_key='task-unrelated-start'), task_suffix='unrelated'),
                            lambda: s4apply(f, s4command(f, 'cancel')),
                            lambda: validate_control_write(f.conn, org_slug='scratch', deadline=time.monotonic()+5)):
                        try:
                            operation()
                        except (ValueError, RuntimeError) as exc:
                            assert 'digest' in str(exc), ('wrong full-reader refusal', str(exc))
                        else:
                            raise AssertionError('write/admission accepted unrelated corrupt history')
                else:
                    # Each independent fixture below avoids one defect masking
                    # another and observes a route error, never empty success.
                    pass
            if case == 'task_corruption':
                for defect in ('hash', 'orphan_visit', 'pin', 'ownership', 'native_metadata', 'pending_callback'):
                    with s4fixture() as f:
                        if defect == 'hash':
                            damage(f, 'workflow_seq_events', 'UPDATE workflow_seq_events SET event_digest=? WHERE run_id=?',
                                ('0'*64, f.ids.run_id))
                        elif defect == 'orphan_visit':
                            damage(f, 'workflow_seq_visits', 'UPDATE workflow_seq_visits SET run_id=? WHERE id=?',
                                ('missing-run', f.ids.visit_id))
                        elif defect == 'pin':
                            damage(f, 'workflow_seq_runs', 'UPDATE workflow_seq_runs SET settings_id=? WHERE id=?',
                                ('missing-settings', f.ids.run_id))
                        elif defect == 'native_metadata':
                            damage(f, 'task_results', 'UPDATE task_results SET decision_json=? WHERE id=?',
                                ('{"action":"workflow_start","workflow":{"identity":"release/happyranch/coding"}}', f.actor.result_row_id))
                        elif defect == 'pending_callback':
                            s4closed(f, f.ids.visit_id, summary=s4bsummary(), terminal='success', positive=False)
                            baseline = asyncio.run(s7read(f, '/tasks/' + f.ids.visit_task_id + '/sequential-workflows'))
                            assert [run['id'] for run in baseline['runs']] == [f.ids.run_id]
                            assert baseline['runs'][0]['progress'] == 'result_pending_settlement'
                            evidence = f.conn.execute("SELECT result_id,evidence_bytes FROM workflow_seq_evidence "
                                "WHERE visit_id=? AND kind='terminal'", (f.ids.visit_id,)).fetchone()
                            assert evidence[0] is None and s4row(f, 'workflow_seq_visits', f.ids.visit_id)['result_id'] is None
                            callback = json.loads(evidence[1])['callback']['result_id']
                            damage(f, 'task_results', 'UPDATE task_results SET decision_json=? WHERE id=?',
                                ('{"action":"workflow_start","workflow":{"identity":"release/happyranch/coding"}}', callback))
                        else:
                            damage(f, 'workflow_task_ownership', 'UPDATE workflow_task_ownership SET owner_id=? WHERE task_id=?',
                                ('missing-owner', f.ids.visit_task_id))
                        body = asyncio.run(s7read(f, '/tasks/' + f.ids.visit_task_id + '/sequential-workflows', expected=409))
                        assert body['detail']['code'] == 'history_unverified' and 'runs' not in body['detail'], defect
                        print('PASS S7a task_corruption', defect, flush=True)
                with s5fixture() as f:
                    damage(f, 'workflow_seq_source_memberships',
                        'DELETE FROM workflow_seq_source_memberships WHERE source_task_id=?', (f.source.id,))
                    body = asyncio.run(s7read(f, '/tasks/' + f.source.id + '/sequential-workflows', expected=409))
                    assert body['detail']['code'] == 'history_unverified' and 'runs' not in body['detail']
                    print('PASS S7a task_corruption wait_membership', flush=True)
            print('PASS S7a', case, flush=True)
            continue
        if case == 'plural_links':
            with s5fixture() as f:
                body = asyncio.run(s7read(f, '/tasks/' + f.source.id + '/sequential-workflows'))
                expected = {ids.run_id for ids in f.batch_ids}
                assert body['format'] == 'workflow-sequential-task-runs@2'
                assert {run['id'] for run in body['runs']} == expected and len(body['runs']) == 2, 'plural_links: source runs collapsed'
                assert {run['id'] for run in asyncio.run(s7read(f, path))['runs']} == expected
                for ids in f.batch_ids:
                    for task in (ids.carrier_task_id, ids.visit_task_id):
                        linked = asyncio.run(s7read(f, '/tasks/' + task + '/sequential-workflows'))
                        assert [run['id'] for run in linked['runs']] == [ids.run_id], 'plural_links: foreign member/task link'
                    detail = asyncio.run(s7read(f, path + '/' + ids.run_id))
                    visit, assignment = detail['visits'][0], next(a for a in detail['assignments'] if a['id'] == detail['visits'][0]['assignment_id'])
                    assert assignment['principal'] == 's3_author' and assignment['principal_source'] == 'bundled'
                    assert assignment['origins'] == dict(model='agent_default', reasoning_effort='agent_default')
                    assert assignment['effective'] == dict(model='target-model', reasoning_effort='high')
                    assert visit['native']['kind'] == 'engine_authenticated' and visit['content_provenance'] == 'agent_reported'
                asyncio.run(s7read(f, path, expected=401, headers={}))
                asyncio.run(s7read(f, path, expected=422, params={'unexpected': 'query'}))
                asyncio.run(s7read(f, path, expected=422, content=b'x'))
                asyncio.run(s7read(f, '/tasks/missing/sequential-workflows', expected=404))
                unrelated = asyncio.run(s7read(f, '/tasks/s5-parent/sequential-workflows'))
                assert unrelated['storage'] == 'readable' and unrelated['runs'] == []
                s5release(f)
                s5hold(f, 0)
                f.ids = f.batch_ids[1]
                s4closed(f, f.ids.visit_id, summary=s4bsummary(outcome='finish'), terminal='success')
                s4baccept(f)
                s6badditional(f)
                mixed = asyncio.run(s7read(f, '/tasks/' + f.source.id + '/sequential-workflows'))
                assert len(mixed['runs']) == 3 and {item['state'] for item in mixed['runs']} == {'running', 'held', 'finished'}, 'plural_links: later source result or mixed state lost'
                assert [item['id'] for item in mixed['runs']] == sorted(item['id'] for item in mixed['runs'])
        elif case == 'held_cause':
            with s4fixture(recovery=True) as f:
                event = s4held(f)
                held = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert held['run']['state'] == 'held' and held['run']['hold'] == dict(event_id=event, node_id='develop', visit_id=f.ids.visit_id, cause='task_timed_out_without_result'), 'held_cause: missing or inferred cause'
                assert held['run']['progress'] is None and held['run']['active_visit_id'] is None
                for action in ('retry', 'rebrief', 'reassign'):
                    command = s4command(f, action, **({'model': 'changed-model', 'reasoning_effort': None} if action == 'retry' else {}))
                    receipt = json.loads(s4apply(f, command))
                    detail = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                    control = detail['controls'][-1]
                    assert control['action'] == action and control['new_visit_id'] == receipt['new_visit_id']
                    assert (control['actor_task_id'], control['actor_principal'], control['actor_session_id'], control['actor_result_id']) == (f.actor.task_id, f.actor.assigned_agent, f.actor.current_session_id, f.actor.result_row_id)
                    assert control['expected_held_event_id'] == command['expected_held_event_id']
                    latest = detail['visits'][-1]
                    assignment = next(item for item in detail['assignments'] if item['id'] == latest['assignment_id'])
                    assert assignment['predecessor_id'] == detail['visits'][-2]['assignment_id'] and assignment['principal_source'] == 'control'
                    assert assignment['origins'] == dict(model='run', reasoning_effort='clear')
                    assert assignment['effective'] == dict(model='changed-model', reasoning_effort='high')
                    assert assignment['principal'] == ('s3_alt' if action == 'reassign' else 's3_author')
                    s4closed(f, receipt['new_visit_id'])
                    s4hold(f)
                s4apply(f, s4command(f, 'cancel'))
                finished = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert finished['run']['state'] == 'finished' and finished['run']['terminal_outcome'] == 'cancelled'
                assert [item['action'] for item in finished['controls']] == ['retry', 'rebrief', 'reassign', 'cancel']
            # Actual accepted content may report a merge; native provenance authenticates identity only.
            with s4fixture() as f:
                s4closed(f, f.ids.visit_id, summary=s4bsummary(content=b'{"merged":true}'), terminal='success')
                s4baccept(f)
                detail = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert detail['outputs'][0]['content_utf8'] == '{"merged":true}'
                assert detail['outputs'][0]['content_provenance'] == 'agent_reported', 'held_cause: reported merge promoted to verified'
                assert detail['visits'][0]['native']['terminal_digest'] and detail['visits'][0]['native']['outer_digest']
                for ordinal in (2, 3):
                    visit = dict(f.conn.execute('SELECT * FROM workflow_seq_visits WHERE ordinal=?', (ordinal,)).fetchone())
                    s4closed(f, visit['id'], summary=s4bsummary(), terminal='success')
                    s4baccept(f, visit['id'])
                terminal = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert terminal['run']['state'] == 'finished' and terminal['run']['terminal_outcome'] == 'completed'
            with s4fixture() as f:
                queued = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert queued['run']['state'] == 'running' and queued['run']['progress'] == 'queued'
                s4closed(f, f.ids.visit_id, summary=s4bsummary(), terminal='success', positive=False)
                pending = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert pending['run']['state'] == 'running' and pending['run']['progress'] == 'result_pending_settlement'
                s4apply(f, s4command(f, 'cancel'))
                cancelling = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert cancelling['run']['state'] == 'running' and cancelling['run']['progress'] == 'cancelling'
                assert cancelling['run']['active_visit_id'] == f.ids.visit_id and cancelling['run']['terminal_outcome'] is None
                s4outer(f, f.ids.visit_id)
                s4finish(f)
                assert asyncio.run(s7read(f, path + '/' + f.ids.run_id))['run']['terminal_outcome'] == 'cancelled'
            with s5fixture() as f:
                s5release(f)
                for index, outcome in enumerate(('pause', 'reject')):
                    f.ids = f.batch_ids[index]
                    s4closed(f, f.ids.visit_id, summary=s4bsummary(outcome=outcome), terminal='success')
                    s4baccept(f)
                    detail = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                    if outcome == 'pause':
                        assert detail['run']['state'] == 'held' and detail['run']['hold']['cause'] == 'declared_edge'
                    else:
                        assert detail['run']['state'] == 'finished' and detail['run']['terminal_outcome'] == 'failed'
            with s4fixture() as f:
                changed = replace(f.agents['s3_author'], executor='opencode', model='provider/model', reasoning_effort=None)
                (f.root / 'org/agents/s3_author.md').write_text(render_agent_text(changed))
                f.coordinator.synchronize_all_dependencies()
                f.org.workflow_authority.publish_current(publisher='private-s7a-drift')
                s4hold(f, unavailable=True)
                detail = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                assert detail['run']['hold']['cause'] == 'assignee_unavailable' and detail['visits'][0]['native']['result_id'] is None
            with s4fixture() as f:
                s4closed(f, f.ids.visit_id, summary=s4bsummary(), terminal='failure', native_status='failed', classification='unknown')
                s4baccept(f)
                detail = asyncio.run(s7read(f, path + '/' + f.ids.run_id))
                visit = detail['visits'][0]
                native_result = f.conn.execute('SELECT id FROM task_results WHERE task_id=?', (f.ids.visit_task_id,)).fetchone()[0]
                assert visit['native']['result_id'] == native_result and visit['accepted_result_id'] is None, 'held_cause: native callback and accepted result collapsed'
                assert detail['run']['hold']['cause'] == 'task_failed_after_result' and detail['outputs'] == []
        elif case == 'history_label':
            with s4fixture() as f:
                ids = s7legacy(f)
                old = asyncio.run(s7read(f, '/workflows/sequential/runs/' + ids.run_id))
                detail = asyncio.run(s7read(f, path + '/' + ids.run_id))
                assert detail['abi'] == '@1' and detail['history_label'] == 'historical_v1', 'history_label: @1 presented as current @2'
                assert detail['detail'] == old and old['format'] == 'workflow-sequential-run-view@1'
                legacy_list = asyncio.run(s7read(f, '/workflows/sequential/runs'))
                assert legacy_list['runs'] == [old['run']], 'history_label: @1 list lost retained history in mixed storage'
                body = asyncio.run(s7read(f, path))
                assert {item['abi'] for item in body['runs']} == {'@1', '@2'}
                historical = next(item for item in body['runs'] if item['abi'] == '@1')
                assert historical['history_label'] == 'historical_v1' and historical['run'] == old['run']
                linked = asyncio.run(s7read(f, '/tasks/s7-source/sequential-workflows'))
                assert linked['runs'] == [historical]
                singular = asyncio.run(s7read(f, '/tasks/s7-source/sequential-workflow'))
                assert singular == dict(format='workflow-sequential-task-link@1', task_id='s7-source', run=old['run'])
        elif case == 'unavailable':
            with s4fixture() as f:
                from runtime.workflows import sequential_views
                real = sequential_views._ReadBudget
                for injected in (dict(deadline=time.monotonic()-1), dict(sql_limit=0), dict(consumed=64*1048576), dict(traversed=65536)):
                    with patch.object(sequential_views, '_ReadBudget', lambda **kw: real(**dict(kw, **injected))):
                        value = asyncio.run(s7read(f, path, expected=409))
                        assert value['detail']['state'] == 'unavailable' and value['detail']['code'] == 'read_budget_exhausted', 'unavailable: budget refusal became empty runs'
                        assert 'runs' not in value['detail']
                cache = dict(f.org.workflow_authority._cache)
                f.org.workflow_authority._cache.clear()
                try:
                    value = asyncio.run(s7read(f, path, expected=409))
                    assert value['detail']['code'] == 'authority_unverified'
                finally:
                    f.org.workflow_authority._cache.update(cache)
                f.conn.execute('CREATE VIEW workflow_seq_incoherent AS SELECT 1')
                f.conn.commit()
                value = asyncio.run(s7read(f, path, expected=409))
                assert value['detail']['state'] == 'unavailable' and value['detail']['code'] == 'history_unverified'
                f.conn.execute('DROP VIEW workflow_seq_incoherent')
                f.conn.commit()
                assert len(asyncio.run(s7read(f, path))['runs']) == 1
                async def bounded_lock_wait():
                    async with f.org.db_lock:
                        with patch.object(sequential_views, '_ReadBudget', lambda **kw: real(**dict(kw, deadline=time.monotonic()+0.05))):
                            value = await s7read(f, path, expected=409)
                            assert value['detail']['code'] == 'read_budget_exhausted', 'unavailable: lock deadline classified as authority failure'
                asyncio.run(bounded_lock_wait())
            # Genuine absent storage, no fake successful history-reader response.
            with s3_fixture() as f:
                from runtime.infrastructure.workflow_task_ownership import OWNERSHIP_DDL, binding_view_ddl
                ownership = [dict(row) for row in f.conn.execute('SELECT * FROM workflow_task_ownership')]
                f.conn.execute('DROP VIEW workflow_task_owner_bindings')
                for kind, name in f.conn.execute("SELECT type,name FROM sqlite_schema WHERE name GLOB 'workflow_seq_*' AND type IN ('view','trigger')").fetchall():
                    f.conn.execute('DROP ' + kind + ' "' + name + '"')
                f.conn.execute('PRAGMA foreign_keys=OFF')
                for name, in f.conn.execute("SELECT name FROM sqlite_schema WHERE name GLOB 'workflow_seq_*' AND type='table'").fetchall():
                    f.conn.execute('DROP TABLE "' + name + '"')
                f.conn.execute('DROP TABLE workflow_task_ownership')
                f.conn.execute(OWNERSHIP_DDL)
                for row in ownership:
                    assert row['kind'] == 'legacy' and row['owner_id'] is None
                    row['version'] = 1
                    f.conn.execute('INSERT INTO workflow_task_ownership (' + ','.join(row) + ') VALUES (' + ','.join('?' for _ in row) + ')', tuple(row.values()))
                f.conn.execute(binding_view_ddl('J', coding_extension=True))
                f.conn.commit()
                f.conn.execute('PRAGMA foreign_keys=ON')
                value = asyncio.run(s7read(f, path))
                assert value['storage'] == 'absent' and value['runs'] == [], 'unavailable: genuine absence misclassified'
        print('PASS S7a', case, 'served route/private fixtures; SELECT-only inventory + SQL evidence', flush=True)

    def s8b_selection(workspace, *, digest='1'*64):
        from runtime.workflows.sequential_coding_final_records import CodingFinalSelection
        change = dict(format='workflow-sequential-code-change@1', epoch=1, head='b'*40,
            subject=dict(repository_id='workflow-repository:'+'1'*64, repo_key='private', origin_digest='2'*64,
                object_format='sha1', base='a'*40, scope=['runtime']),
            pr=dict(repository='synthetic/private', number=1, url='https://github.com/synthetic/private/pull/1'))
        results = [dict(ref=dict(slot=slot, contract=contract, epoch=1, producer_visit='visit-'+role,
            task_id='task-'+role, session_id='sid-'+role, result_id=index+1, digest='3'*64),
            principal=role, carrier_digest='4'*64, terminal_digest='5'*64, outer_digest='6'*64)
            for index, (role, slot, contract) in enumerate((('developer','change','code-change@1'),
                ('reviewer','review','independent-code-review@1'), ('qa','qa','code-qa@1')))]
        return CodingFinalSelection.model_validate_json(s4bytes(dict(format='workflow-sequential-coding-final-selection@1',
            org_slug='scratch', run_id='run', visit_id='final', task_id='final-task', principal='manager',
            session_id='final-sid', definition_digest=digest, start_digest='7'*64, cas=3,
            last_event_digest='8'*64, input_selection_digest='9'*64, authority_generation=1,
            authority_digest='a'*64, change=change, contributors=['developer'], results=results,
            native=dict(root_task_id='source', invocation_id='invocation', request_id='request', handle_id='handle',
                backend='linux-systemd-cgroup-v2', pause_generation=0, org_root=str(workspace.parent.parent),
                workspace_root=str(workspace)))))

    async def s8b_transports(f):
        import asyncio
        import httpx
        from cli.main import build_parser
        from runtime.daemon.app import create_app
        from runtime.daemon.state import DaemonState
        from runtime.runtime import port_file
        task, principal, sid = f.ids.visit_task_id, 's3_author', 's8b-session'
        f.conn.execute("UPDATE workflow_seq_visits SET session_id=?,state='running' WHERE id=?", (sid, f.ids.visit_id))
        f.conn.execute("UPDATE tasks SET current_session_id=?,status='in_progress' WHERE id=?", (sid, task))
        f.conn.commit()
        f.org.sessions.set_active(task, principal, sid, org_slug='scratch')
        state = DaemonState(runtime=RuntimeDir(f.root.parent.parent), settings=Settings())
        state.orgs['scratch'], state.profile_coordinator = f.org, f.coordinator
        app = create_app(state)
        port_file().write_text('43210')
        loop = asyncio.get_running_loop()
        real_client = httpx.Client
        try:
            async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url='http://private') as client:
                def transport(request):
                    response = asyncio.run_coroutine_threadsafe(client.send(request), loop).result(timeout=10)
                    return httpx.Response(response.status_code, content=response.content, headers=response.headers)
                for form in ('repository-resolve', 'repository-bind', 'repository-preflight', 'finalize'):
                    declaration = dict(format='workflow-sequential-repository-command@1', repo_key='private', base='a'*40, scope=['runtime'])
                    if form == 'finalize':
                        workspace = Path(os.environ['HAPPYRANCH_DAEMON_HOME']) / 'org/workspaces/manager'
                        declaration = dict(format='workflow-sequential-finalize-command@1', operation_key='no-final',
                            repository_path=str(workspace), change=s8b_selection(workspace).change.model_dump(mode='json'))
                    payload = Path(os.environ['HAPPYRANCH_DAEMON_HOME']) / 's8b-command.json'
                    payload.write_bytes(s4bytes(declaration))
                    argv = ['workflows','sequential',form,'--org','scratch','--session-id',sid,'--json']
                    if form != 'repository-preflight':
                        argv += ['--from-file', str(payload)]
                    out, err = io.StringIO(), io.StringIO()
                    before, changes = tuple(f.conn.iterdump()), f.conn.total_changes
                    def invoke():
                        with redirect_stdout(out), redirect_stderr(err), patch.object(httpx, 'Client',
                                lambda **kw: real_client(transport=httpx.MockTransport(transport), **kw)):
                            args = build_parser().parse_args(argv)
                            try:
                                args.func(args)
                            except SystemExit as exc:
                                return exc.code
                        return 0
                    status = await asyncio.to_thread(invoke)
                    assert status == 2 and not out.getvalue() and 'sequential_domain_transport_unavailable' in err.getvalue(), (
                        'new_transport_refused', form, status, out.getvalue(), err.getvalue())
                    assert tuple(f.conn.iterdump()) == before and f.conn.total_changes == changes, form+' wrote rows'
                    assert payload.read_bytes() == s4bytes(declaration)
                    print('PASS S8b new_transport_refused CLI + real route', form, '409 zero writes', flush=True)
        finally:
            state.metrics_store.close()
            state.direct_connect_authority_store.close()

    for case in (S8B_CASES if s8b_case or not sys.argv[1:] else ()):
        if s8b_case not in (None, 'all', case):
            continue
        from runtime.workflows import sequential_release as release
        from scripts import setup_sequential_coding as setup
        from runtime.workflows.sequential_history import _ReadBudget
        import asyncio
        if case == 'new_transport_refused':
            with s4fixture() as f:
                asyncio.run(s8b_transports(f))
            # Distinct local risk: even an @1-shaped selection carrying the
            # registered generic digest must refuse before filesystem/Git effects.
            from cli.commands import workflow_sequential_finalize as final, workflow_sequential_final_journal as journal
            from cli.commands.workflow_sequential_transport import RemoteSelection
            import httpx
            with tempfile.TemporaryDirectory(prefix='s8b-local-') as private:
                workspace = Path(private) / 'org/workspaces/manager'
                workspace.mkdir(parents=True)
                selected = s8b_selection(workspace, digest=release.STAGED_GENERIC[('release/happyranch/coding',3)].pin.definition_digest)
                before = tuple(workspace.rglob('*'))
                for label, action in (
                    ('journal', lambda: journal.reserve_attempt(selected, reselect=lambda: selected)),
                    ('final adapter', lambda: final.execute_selected_final(selection=SimpleNamespace(select=lambda **kw: selected),
                        task_id=selected.task_id, principal=selected.principal, session_id=selected.session_id,
                        change=s4bytes(selected.change.model_dump(mode='json')), operation_key='no-final', repository_path=workspace)),
                    ('remote selection', lambda: RemoteSelection(httpx.Client(base_url='http://private', transport=httpx.MockTransport(
                        lambda request: httpx.Response(200, content=s4bytes(selected.model_dump(mode='json'))))),
                        'scratch', selected.session_id).current(s4bytes(selected.change.model_dump(mode='json'))))):
                    try:
                        action()
                    except ValueError as exc:
                        assert str(exc) == 'sequential_domain_transport_unavailable', (label, str(exc))
                    else:
                        raise AssertionError('new_transport_refused: '+label+' admitted generic selection')
                    assert tuple(workspace.rglob('*')) == before, label+' changed filesystem'
                    print('PASS S8b new_transport_refused', label, 'no local effects', flush=True)
        elif case in ('legacy_replay', 'old_fresh_refused'):
            with s3_fixture() as f:
                coding = release.read_coding_release()
                definition = dict(f.conn.execute('SELECT * FROM workflow_seq_definitions WHERE identity=? AND version=2',
                    (coding.pin.identity,)).fetchone())
                bindings = [dict(role=role, principal=dict(developer='s3_author', reviewer='s3_review', qa='s3_alt', final_manager='s3_manager')[role])
                    for role, _ in coding.definition.roles]
                saved = s4bytes(dict(format='workflow-sequential-settings-storage@1', definition=coding.pin.model_dump(mode='json'),
                    bindings=bindings, limits=coding.definition.limits.model_dump(mode='json'), admission='Allowed'))
                for generation, key in ((1, 's8b-defaults'), (2, 's8b-original')):
                    setup._write(f.conn, 'scratch', 'admission', SimpleNamespace(operation_key=key, definition=coding.pin,
                        expected_generation=generation-1), dict(write=dict(definition_id=definition['id'], generation=generation, raw=saved)))
                f.conn.commit()
                if case == 'legacy_replay':
                    ids = s7legacy(f)
                    from runtime.workflows.sequential_start import _admitted_replay
                    from runtime.workflows.sequential_definition import parse_start
                    row = s4row(f, 'workflow_seq_runs', ids.run_id)
                    claim = RetryClaim.from_task(f.db.get_task(row['source_task_id']), result_row_id=row['source_result_id'])
                    before, changes = tuple(f.conn.iterdump()), f.conn.total_changes
                    with f.db.coherent_read_view() as reader:
                        replay = _admitted_replay(reader, f.org, claim, parse_start(row['start_bytes']), _ReadBudget())
                        original = setup._inspect(reader, org='scratch', action='admission-show', command=None,
                            key='s8b-original', compiled=coding, budget=_ReadBudget())
                        command = setup.AdmissionCommand.model_validate(original['command'])
                        again = setup._inspect(reader, org='scratch', action='admission', command=command,
                            key=command.operation_key, compiled=coding, budget=_ReadBudget())
                    assert replay == ids, 'legacy_replay changed original admission IDs'
                    assert original == again and original['write'] is None
                    receipt = f.conn.execute('SELECT receipt_bytes FROM workflow_seq_settings_operations WHERE operation_key=?',
                        ('s8b-original',)).fetchone()[0]
                    assert s4bytes(original['receipt']) == receipt, 'legacy_replay changed receipt bytes'
                    assert tuple(f.conn.iterdump()) == before and f.conn.total_changes == changes
                    body = asyncio.run(s7read(f, '/workflows/sequential/runs/'+ids.run_id))
                    assert body['run']['id'] == ids.run_id, 'legacy_replay selected history unavailable'
                else:
                    command = setup.AdmissionCommand(format='workflow-sequential-coding-admission@1', operation_key='fresh-allow',
                        definition=coding.pin, expected_generation=2, admission='Allowed')
                    before, changes = tuple(f.conn.iterdump()), f.conn.total_changes
                    with f.db.coherent_read_view() as reader:
                        try:
                            setup._inspect(reader, org='scratch', action='admission', command=command,
                                key=command.operation_key, compiled=coding, budget=_ReadBudget())
                        except ValueError as exc:
                            assert str(exc) == 'sequential_coding_registration_only'
                        else:
                            raise AssertionError('old_fresh_refused: setup still offers a fresh admission write')
                        generic = release.read_generic_coding_release()
                        registered = setup._inspect(reader, org='scratch', action='register', command=None,
                            key=None, compiled=generic, budget=_ReadBudget())
                        assert generic.pin == release.GENERIC_CATALOG[('release/happyranch/coding',3)].pin
                        assert registered['registered'] and registered['write'] is None
                        assert registered['definition'] == generic.pin.model_dump(mode='json')
                    # Fresh @1 v2 selection is unchanged; no runtime admission is claimed.
                    assert release.select_bundled_release(coding.pin) == coding
                    assert release.is_bundled_definition(coding.pin)
                    try:
                        release.is_bundled_definition(coding.pin.model_copy(update={'version': 1}))
                    except ValueError as exc:
                        assert str(exc) == 'coding_fresh_start_retired'
                    else:
                        raise AssertionError('old_fresh_refused: retired v1 fresh start admitted')
                    try:
                        release.is_bundled_definition(generic.pin)
                    except ValueError as exc:
                        assert str(exc) == 'sequential_release_pin_mismatch'
                    else:
                        raise AssertionError('old_fresh_refused: generic pin became publicly startable')
                    f.db.insert_task(TaskRecord(id='s8b-context', assigned_agent='s3_manager', team='engineering',
                        task_type='task', status='in_progress', current_session_id='s8b-context-sid', brief='Private discovery'))
                    f.org.sessions.set_active('s8b-context','s3_manager','s8b-context-sid',org_slug='scratch')
                    before, changes = tuple(f.conn.iterdump()), f.conn.total_changes
                    from runtime.workflows.sequential_views import read_start_context
                    async def context(selector):
                        return await read_start_context(f.org, task_id='s8b-context', principal='s3_manager',
                            session_id='s8b-context-sid', selector=selector, revalidate=lambda: None)
                    body = asyncio.run(context(None)).model_dump(mode='json')
                    assert body['format'] == 'workflow-sequential-start-context@1' and body['start_format'] == 'workflow-sequential-start@1'
                    assert [item['pin']['version'] for item in body['definitions']] == [2]
                    try:
                        asyncio.run(context('release/happyranch/coding@3'))
                    except ValueError as exc:
                        assert str(exc) == 'sequential_definition_unavailable'
                    else:
                        raise AssertionError('old_fresh_refused: public discovery offered v3')
                    assert tuple(f.conn.iterdump()) == before and f.conn.total_changes == changes
                    # Close the private attachment before the real cooperative
                    # offline operator. No successful custody stub or live DB.
                    path = f.db.path
                    f.org.close()
                    home = Path(os.environ['HAPPYRANCH_DAEMON_HOME'])
                    (home / 'runtimes.yaml').write_text(json.dumps(dict(active=str(f.root.parent.parent), registered=[str(f.root.parent.parent)])))
                    environment = {key:value for key,value in os.environ.items() if key not in setup._MARKERS}
                    original_bytes = path.read_bytes()
                    with patch.dict(os.environ, environment, clear=True):
                        registered = setup.operation(SimpleNamespace(action='register', runtime_root=f.root.parent.parent,
                            org='scratch', confirm_cooperative_offline=True, operation_key=None, backup=None,
                            backup_sha256=None))
                    assert registered['definition'] == generic.pin.model_dump(mode='json'), 'old_fresh_refused: operator registered v2'
                    assert registered['registered'] and path.read_bytes() == original_bytes
        else:
            from cli.commands import workflow_sequential_final_journal as journal
            from runtime.workflows.sequential_coding_final_records import read_final_selection
            with tempfile.TemporaryDirectory(prefix='s8b-uncertain-') as private:
                workspace = Path(private) / 'org/workspaces/manager'
                workspace.mkdir(parents=True)
                selected = s8b_selection(workspace)
                attempt = journal.reserve_attempt(selected, reselect=lambda: selected)
                # Original partial records are evidence, never replay permission.
                records = {'selected.json': s4bytes(selected.model_dump(mode='json')),
                    'intent.json': b'{"original":"uncertain intent"}',
                    'action-started.json': b'{"original":"command may have run"}'}
                for name, raw in records.items():
                    (attempt.directory / name).write_bytes(raw)
                assert read_final_selection(records['selected.json']) == selected
                try:
                    journal.reserve_attempt(selected, reselect=lambda: selected)
                except FileExistsError:
                    pass
                else:
                    raise AssertionError('uncertain_final_preserved: reserved original task again')
                assert {p.name:p.read_bytes() for p in attempt.directory.iterdir()} == records
        print('PASS S8b', case, 'original rows/receipts preserved; no live operation', flush=True)

