            conn.execute('UPDATE audit_log SET id=? WHERE id=?', (temporary, operation))
            conn.execute('UPDATE audit_log SET id=? WHERE id=?', (operation, original))
            conn.execute('UPDATE audit_log SET id=? WHERE id=?', (original, temporary))

